/// <summary>
/// Batch class that updates AVAHK2NDG table records for all NDG item ids with NDX related data
/// </summary>
public class AVAUpdateHK2ForNDG extends RunBaseBatch
{
    CompanyId   allowedCompanyId    = 'NDX';
    CompanyId   targetCompanyId     = 'NDG';

    #define.CurrentVersion(1)
    #define.Version1(1)
    #localmacro.CurrentList
        allowedCompanyId,
        targetCompanyId
    #endmacro

}

Method.Source:
public static void main(Args _args)
{
    AVAUpdateHK2ForNDG  updateHK2ForNDG;

    updateHK2ForNDG = AVAUpdateHK2ForNDG::construct();

    if(updateHK2ForNDG.prompt())
    {
        updateHK2ForNDG.runOperation();
    }
}

server static AVAUpdateHK2ForNDG construct()
{
    return new AVAUpdateHK2ForNDG();
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <returns>description</returns>
public static ClassDescription description()
{
    return "@NDX:NXAUpdateHK2ForNDG";
}

