/// <summary>
/// canRunInBewSession
/// </summary>
/// <returns>true</returns>
protected boolean canRunInNewSession()
{
    boolean ret;
    ret = true;
    return ret;
}

/// <summary>
/// runs class logic
/// </summary>
public void run()
{
    if(curExt() != allowedCompanyId)
    {
        throw error(strFmt("@NDX:NXAUpdateHK2WrongCompany", allowedCompanyId));
    }

    info("@NDX:NXAUpdateHK2StartInfo");

    this.selectItems();

    info("@NDX:NXAUpdateHK2FinishInfo");
}

/// <summary>
/// loops through all NDG items and compares NDX values for information updating
/// </summary>
public void selectItems()
{
    InventTable inventTable_target, inventTable_allowed;

    // kernel adds a DataAreaId condition to simple table field joins (A.ItemId == B.ItemId), as a workaround A.ItemId == B.ItemId+'' is needed
    while select crosscompany: [targetCompanyId, allowedCompanyId] inventTable_target
        join inventTable_allowed
        where inventTable_target.ItemId == inventTable_allowed.ItemId+''
        && inventTable_target.DataAreaId == targetCompanyId
        && inventTable_allowed.DataAreaId == allowedCompanyId
    {
        Price hk2Value = 0;

        if(inventTable_allowed.inventItemSetupSupplyType().DefaultOrderType == ReqPOType::Production)
        {
            hk2Value = inventTable_allowed.inventTableModuleInvent().NDX_showHK2current();
        }
        else if(inventTable_allowed.inventItemSetupSupplyType().DefaultOrderType == ReqPOType::Purch)
        {
            hk2Value = inventTable_allowed.inventTableModulePurch().NDX_showHK2PriceDisc();
        }

        this.updateHK2NDGTable(inventTable_target.ItemId, hk2Value);
    }
}

/// <summary>
/// updates a AVAHK2NDG record or creates a new one for provided item id
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_hk2Value">Price</param>
public void updateHK2NDGTable(ItemId _itemId, Price _hk2Value = 0)
{
    AVAHK2NDG hk2Ndg = AVAHK2NDG::findItemId(_itemId, true);

    ttsbegin;

    if(hk2Ndg)
    {
        hk2Ndg.HK2p1000 = _hk2Value;
        hk2Ndg.update();
    }
    else
    {
        hk2Ndg.ItemId   = _itemId;
        hk2Ndg.HK2p1000 = _hk2Value;
        hk2Ndg.insert();
    }

    ttscommit;
}

/// <summary>
/// unpack
/// </summary>
/// <param name = "packedClass">packedClass</param>
/// <returns>boolean</returns>
public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}
